def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sources = []

    # Complete single-cell gaps between equal-colored horizontal segments.
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color and grid[r][c] == 0 and grid[r][c + 1] == color:
                out[r][c] = color
                sources.append((r, c, color))

    # Vertical strokes also extend upward from the top of each vertical run.
    for c in range(w):
        r = 0
        while r < h:
            color = grid[r][c]
            if not color:
                r += 1
                continue
            end = r
            while end + 1 < h and grid[end + 1][c] == color:
                end += 1
            if end > r:
                sources.append((r, c, color))
            r = end + 1

    # Extend each gap or vertical stroke upward, stopping at any occupied cell.
    for r, c, color in sorted(sources):
        rr = r - 1
        while rr >= 0 and out[rr][c] == 0:
            out[rr][c] = color
            rr -= 1

    return out
