def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    for c in range(w):
        # A vertical stroke is a same-colored run touching the bottom edge.
        base = grid[h - 1][c]
        if base == 0:
            continue
        start = h - 1
        while start > 0 and grid[start - 1][c] == base:
            start -= 1

        # Horizontal strokes crossing this column have matching colors
        # immediately to either side.
        events = []
        for r in range(h):
            if c > 0 and c + 1 < w:
                color = grid[r][c - 1]
                if color != 0 and grid[r][c + 1] == color:
                    events.append((r, color))

        if not events:
            continue

        # Extend the vertical stroke upward to the lowest crossing. Above
        # each crossing, the next crossing determines the color of that band.
        last_event_row = events[-1][0]
        for r in range(start, last_event_row, -1):
            out[r][c] = base

        for r in range(last_event_row + 1):
            next_event = next(((er, color) for er, color in events if er >= r), None)
            if next_event is not None:
                out[r][c] = next_event[1]

    return out
